{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Bromfenac, a benzoyl arylacetic acid NSAID structurally close to the query, had absolute oral bioavailability of 67% in fasting healthy subjects, directly supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Ketanserin, a benzoyl-containing drug, had absolute bioavailability of 49.3 ± 18.0% in fasted subjects after a 40 mg tablet, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Thalidomide, a poorly soluble but highly permeable drug, showed probably high oral bioavailability of 80–100% in fasting healthy volunteers, supporting that high F can occur despite challenging physicochemical features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "p-Aminobenzoic acid, a small aromatic carboxylic acid, had oral bioavailability of 90.1 ± 8.7%, supporting high F for the carboxylic acid-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Tranexamic acid, a polar amino acid, still achieved 33.4% systemic bioavailability in fasting volunteers, reinforcing that even less permeable carboxylic acids exceed the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues with direct oral bioavailability measurements exceed 20% (range approximately 33–90%), including the structurally closest bromfenac at 67%; therefore the query is predicted to have high absolute oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself; prediction is based on high-transfer experimental analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

